import {resetUsers,usersScreen,mailScreen,bindUsers,usersClick,loadUsersTab} from './users.js';
import {backend} from './backend.js';
import {loadStats,statsCards} from './analytics.js';
import {loadAbout,aboutEditor,bindAboutEditor} from './about.js';
import {escape as e} from './store.js';
import {subjectCatalog,subjectsScreen,bindSubjects,removeSubject} from './subjects.js';
const types={materials:'Materials',lectures:'Lecture Recordings',lectureNotes:'Lecture Notes',cases:'Case briefs',flashcards:'Flashcards',quizSets:'Quiz sets',quizQuestions:'Quiz questions'};
let state={status:'idle',items:{},type:'materials',query:'',error:''},busy=false;
let ui;
export function initAdmin(callbacks){ui=callbacks;}
let loadEpoch=0;
export function resetAdmin(){loadEpoch++;state={status:'idle',items:{},type:'materials',query:'',error:''};resetUsers();}
export async function loadAdmin(){const epoch=++loadEpoch,owner=backend.user()?.id;state.status='loading';state.error='';ui.render();try{await backend.refreshSession();if(!backend.user()){state.status='signedout';return;}if(!await backend.isAdmin()){state.status='denied';return;}await subjectCatalog.load();await loadAbout();await loadStats();const results=await Promise.all(Object.keys(types).map(async type=>[type,await backend.cloudRead(type)]));if(epoch!==loadEpoch||backend.user()?.id!==owner)return;state.items=Object.fromEntries(results);state.status='ready';await loadUsersTab(state.type,ui);}catch(err){if(epoch!==loadEpoch)return;state.status='error';state.error=err.message;}finally{ui.render();}}
export function renderAdmin(){const heading='<div class="heading"><div><span class="eyebrow">LEXAMAH ADMINISTRATION</span><h1>Your content command centre.</h1><p>Publish resources, manage study content and upload course files.</p></div><button class="btn" id="admin-refresh">Refresh</button></div>';
if(state.status==='idle'||state.status==='loading')return heading+'<div class="empty"><h3>Checking administrator access…</h3><p>Access is verified with Supabase.</p></div>';
if(state.status!=='ready'){const messages={signedout:['Sign in to manage shared content.','Use your username and password on the Log In page, then return here.'],denied:['Administrator access required.','Your account has not been added to lexamah_admins. Follow the setup guide to grant your own account access.'],error:['The admin dashboard needs setup.',state.error+' Run supabase/setup.sql in your Supabase SQL Editor, then refresh.']};const [title,description]=messages[state.status];return heading+`<div class="empty"><h3>${title}</h3><p>${e(description)}</p><button class="btn primary" data-route="login">Log In →</button></div>`;}
const metrics=statsCards();const tabs=`<div class="admin-tabs">${Object.entries({...types,subjects:'Subjects',about:'About LexAmah',users:'Users',mail:'Bulk Email'}).map(([key,label])=>`<button class="btn ${state.type===key?'primary':''}" data-admin-type="${key}">${label}</button>`).join('')}</div>`;if(state.type==='users')return heading+metrics+tabs+usersScreen();if(state.type==='mail')return heading+metrics+tabs+mailScreen();if(state.type==='subjects')return heading+metrics+tabs+subjectsScreen();if(state.type==='about')return heading+metrics+tabs+aboutEditor();
const items=state.items[state.type]||[],filtered=items.filter(x=>`${x.title||x.name||x.front||x.question} ${x.subject||''}`.toLowerCase().includes(state.query.toLowerCase()));
return heading+metrics+`<div class="notice">Shared library · Published content appears for signed-in students. Uploaded files are private and open through short-lived download links.</div><div class="stats">${[['materials','Materials'],['lectures','Lecture Recordings'],['quizSets','Quiz sets'],['quizQuestions','Questions']].map(([k,v])=>`<div class="stat"><div><small>${v}</small><strong>${state.items[k]?.length||0}</strong><span class="sub">Shared library</span></div></div>`).join('')}</div><div class="admin-tabs">${Object.entries({...types,subjects:'Subjects',about:'About LexAmah',users:'Users',mail:'Bulk Email'}).map(([k,v])=>`<button class="btn ${state.type===k?'primary':''}" data-admin-type="${k}">${v}</button>`).join('')}</div><div class="toolbar"><input id="admin-search" aria-label="Search shared content" placeholder="Search ${types[state.type].toLowerCase()}…" value="${e(state.query)}"><button class="btn primary" id="admin-create">+ Add ${types[state.type].toLowerCase()}</button></div><section class="card"><div class="card-head"><h2>${types[state.type]}</h2><span class="pill">${filtered.length} records</span></div>${filtered.length?filtered.map(x=>`<div class="row"><div class="row-copy"><strong>${e(x.title||x.name||x.front||x.question)}</strong><small>${e(x.subject||'Quiz question')}${x.file_name?` · ${e(x.file_name)}`:''}</small></div><button class="btn" data-admin-edit="${e(x.id)}">Edit</button><button class="btn danger" data-admin-delete="${e(x.id)}">Delete</button></div>`).join(''):'<p class="muted">No records yet. Add your first resource above.</p>'}</section><p class="muted">Personal resources remain in <button class="text-button" data-route="studio">Local Content Studio ↗</button>.</p>`;}
function field(name,label,value='',kind='input',attrs=''){return `<label for="admin-${name}">${label}</label><${kind} id="admin-${name}" name="${name}" ${kind==='input'?`value="${e(value)}"`:''} ${attrs}>${kind==='textarea'?e(value)+'</textarea>':''}`;}
function edit(id){if(state.status!=='ready')return;const type=state.type,x=id?state.items[type].find(x=>x.id===id):{};if(!x)return;if(type!=='quizQuestions'&&!subjectCatalog.options(x.subject).length){ui.toast('Add a subject in the Subjects tab first.');return;}let html='';if(type==='flashcards')html=field('front','Question',x.front,'textarea','required maxlength="4000"')+field('back','Answer',x.back,'textarea','required maxlength="10000"');else if(type==='quizQuestions'){if(!state.items.quizSets.length){ui.toast('Create a shared quiz set first.');return;}html=`<label for="admin-quiz-set">Quiz set</label><select id="admin-quiz-set" name="quiz_set_id" required>${state.items.quizSets.map(q=>`<option value="${e(q.id)}" ${x.quiz_set_id===q.id?'selected':''}>${e(q.name)}</option>`).join('')}</select>`+field('question','Question',x.question,'textarea','required maxlength="4000"')+[0,1,2,3].map(i=>field(`option${i}`,`Option ${'ABCD'[i]}`,x.options?.[i]||'','input','required maxlength="2000"')).join('')+`<label for="admin-correct-index">Correct answer</label><select id="admin-correct-index" name="correct_index">${[0,1,2,3].map(i=>`<option value="${i}" ${Number(x.correct_index)===i?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select>`+field('explanation','Explanation',x.explanation,'textarea','required maxlength="10000"');}else html=field(type==='quizSets'?'name':'title','Title',x.name||x.title,'input','required maxlength="180"')+field('description','Description',x.description,'textarea','maxlength="4000"');if(type!=='quizQuestions')html+=`<label for="admin-subject">Subject</label><select id="admin-subject" name="subject">${subjectCatalog.options(x.subject).map(s=>`<option value="${e(s)}" ${s===x.subject?'selected':''}>${e(s)}${s===x.subject&&!subjectCatalog.names().includes(s)?' (no longer listed)':''}</option>`).join('')}</select>`;if(['materials','lectureNotes','cases'].includes(type))html+=field('body',type==='cases'?'Case brief: facts, issues, decision and reasoning':'Written content',x.body,'textarea','maxlength="100000"');if(type==='cases')html+=field('citation','Verified citation',x.citation);if(['materials','lectureNotes','cases','lectures'].includes(type)){if(type!=='lectures')html+=field('url','Reference URL (optional)',x.url,'input','type="url"');const audio=type==='lectures';html+=`<label for="admin-upload">${x.storage_path?'Replace attached file':audio?'Upload audio recording':'Upload document'}${audio?'':' (optional)'}</label><input id="admin-upload" name="upload" type="file" accept="${audio?'.mp3,.m4a,.aac,.wav,.ogg,.webm,.flac':'.pdf,.docx,.txt,.jpg,.jpeg,.png'}" ${audio&&!x.storage_path?'required':''}><p class="muted">${audio?'Audio only: MP3, M4A, AAC, WAV, OGG, WebM audio or FLAC.':'PDF, DOCX, TXT, JPG or PNG.'} Up to 50 MB.${x.file_name?` Current file: ${e(x.file_name)}.`:''}</p>${x.storage_path&&!audio?'<label class="task"><input type="checkbox" name="detach"><span>Detach current file from this resource</span></label>':''}`;}if(type==='quizSets')html+=field('time_minutes','Time limit (minutes)',x.time_minutes||10,'input','type="number" min="1" max="180" required')+field('difficulty','Difficulty',x.difficulty||'Practice');ui.modal(`${id?'Edit':'Add'} ${types[type].toLowerCase()}`,`<form id="admin-form">${html}<p class="muted" id="admin-form-status" aria-live="polite"></p><div class="actions"><button class="btn primary" id="admin-save">${id?'Save changes':'Publish resource'}</button><button type="button" class="btn" id="admin-cancel">Cancel</button></div></form>`);document.querySelector('#admin-cancel').onclick=()=>{if(!busy)document.querySelector('#dialog').close();};document.querySelector('#admin-form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const submit=document.querySelector('#admin-save'),status=document.querySelector('#admin-form-status');submit.disabled=true;let upload;let saved=false;try{const form=new FormData(ev.target),payload=Object.fromEntries(form);delete payload.upload;if(payload.detach){payload.storage_path=null;payload.file_name=null;payload.file_size=null;payload.mime_type=null;}delete payload.detach;if(payload.url){const u=new URL(payload.url);if(!['http:','https:'].includes(u.protocol))throw new Error('Use an HTTP or HTTPS source URL.');}if(type==='quizQuestions'){payload.options=[0,1,2,3].map(i=>payload[`option${i}`]);[0,1,2,3].forEach(i=>delete payload[`option${i}`]);payload.correct_index=Number(payload.correct_index);}if(type==='quizSets')payload.time_minutes=Number(payload.time_minutes);const file=form.get('upload');if(file?.size){status.textContent='Uploading file…';upload=await backend.upload(file,{audioOnly:type==='lectures'});Object.assign(payload,upload);}if(type==='lectures'){payload.url='';if(!upload&&(!x.storage_path||x.storage_bucket!=='lexamah-audio'||!String(x.mime_type||'').startsWith('audio/')))throw new Error('Upload an audio file before publishing this recording.');}status.textContent='Saving resource…';await backend.cloudSave(type,payload,id);saved=true;document.querySelector('#dialog').close();await ui.reload();await loadAdmin();ui.toast('Published to your shared library.');}catch(err){if(upload&&!saved){try{await backend.deleteFile(upload.storage_path,upload.storage_bucket);}catch{ui.toast('The record was not saved. An uploaded file remains in Storage.');}}status.textContent=err.message;}finally{busy=false;submit.disabled=false;}};}
async function remove(id){const type=state.type,item=state.items[type].find(x=>x.id===id);if(!item)return;ui.modal('Delete shared content?',`<p class="muted">Remove “${e(item.title||item.name||item.front||item.question)}” from the shared library?${type==='quizSets'?' Its questions will also be removed. Sets with saved student attempts cannot be deleted.':''}</p>${item.storage_path?'<label class="task"><input id="admin-delete-file" type="checkbox"><span>Also remove the attached file from Storage</span></label>':''}<p class="muted" id="admin-delete-status" aria-live="polite"></p><div class="actions"><button class="btn danger" id="admin-confirm-delete">Delete resource</button><button class="btn" id="admin-cancel-delete">Keep resource</button></div>`);document.querySelector('#admin-cancel-delete').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#admin-confirm-delete').onclick=async ev=>{ev.target.disabled=true;try{const deleteFile=document.querySelector('#admin-delete-file')?.checked;await backend.cloudDelete(type,id);let message='Resource deleted.';if(deleteFile){try{await backend.deleteFile(item.storage_path,item.storage_bucket||'lexamah-files');}catch{message='Resource deleted; its file remains in Storage. Remove it there if needed.';}}document.querySelector('#dialog').close();await ui.reload();await loadAdmin();ui.toast(message);}catch(err){document.querySelector('#admin-delete-status').textContent=err.message;ev.target.disabled=false;}};}
export function bindAdmin(){if(state.status!=='ready')return;if(['users','mail'].includes(state.type)){bindUsers(ui);return;}if(state.type==='about'){bindAboutEditor(ui);return;}if(state.type==='subjects'){bindSubjects(ui);return;}const search=document.querySelector('#admin-search');if(search)search.oninput=ev=>{state.query=ev.target.value;const pos=ev.target.selectionStart;ui.render();const next=document.querySelector('#admin-search');next.focus();next.setSelectionRange(pos,pos);};}
export async function adminClick(button){if(state.status==='ready'&&await usersClick(button,ui))return true;if(button.dataset.removeSubject){removeSubject(button.dataset.removeSubject,ui);return true;}if(button.id==='admin-refresh'){await loadAdmin();return true;}if(button.dataset.adminType){state.type=button.dataset.adminType;state.query='';ui.render();if(state.status==='ready')await loadUsersTab(state.type,ui);return true;}if(button.id==='admin-create'){edit();return true;}if(button.dataset.adminEdit){edit(button.dataset.adminEdit);return true;}if(button.dataset.adminDelete){await remove(button.dataset.adminDelete);return true;}return false;}
